import { useEffect, useState } from "react";
import { StyleSheet, Text, View, type ViewProps } from "react-native";
import Animated, {
  cancelAnimation,
  Easing,
  ReduceMotion,
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withRepeat,
  withTiming,
} from "react-native-reanimated";
import { useResolveClassNames } from "uniwind";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";

const CYCLE = 1550;
const STAGGER = 140;
const GLYPH = 20;
const GAP = 2;
const CELL = (GLYPH - GAP * 2) / 3;
const EASE = Easing.bezier(0.77, 0, 0.175, 1);

function format(seconds: number) {
  if (seconds < 60) return `${seconds.toFixed(1)}s`;
  const minutes = Math.floor(seconds / 60);
  return `${minutes}m ${(seconds - minutes * 60).toFixed(1)}s`;
}

function Cell({
  index,
  color,
  reduce,
  running,
}: {
  index: number;
  color: string;
  reduce: boolean;
  running: boolean;
}) {
  // 0 → 1 → 0 each cycle: dim and small, then full, then back.
  const pulse = useSharedValue(0);

  useEffect(() => {
    if (!running) {
      cancelAnimation(pulse);
      pulse.value = withTiming(1, { duration: 200 });
      return;
    }
    pulse.value = 0;
    pulse.value = withDelay(
      index * STAGGER,
      withRepeat(
        withTiming(1, {
          duration: CYCLE / 2,
          easing: EASE,
          reduceMotion: ReduceMotion.Never,
        }),
        -1,
        true,
      ),
    );
    return () => cancelAnimation(pulse);
  }, [index, pulse, running]);

  const style = useAnimatedStyle(() => {
    const p = pulse.value;
    return reduce
      ? { opacity: 0.35 + p * 0.45 }
      : { opacity: 0.28 + p * 0.72, transform: [{ scale: 0.72 + p * 0.28 }] };
  }, [reduce]);

  return (
    <Animated.View style={[styles.cell, { backgroundColor: color }, style]} />
  );
}

export type AgentProgressProps = Omit<ViewProps, "children"> & {
  /** Defaults to "Churning". */
  label?: string;
  /** Controlled elapsed time in seconds. Omit it to count from `initialSeconds`. */
  elapsedSeconds?: number;
  /** Where the internal timer starts. Defaults to 0. */
  initialSeconds?: number;
  /** Pauses the internal timer and the glyph. Defaults to true. */
  running?: boolean;
  /** Text size and color utilities, such as `text-base`. */
  className?: string;
  /** Holds the glyph still, independently of the system preference. */
  disableAnimation?: boolean;
};

/**
 * A pulsing 3×3 glyph, a working label and an elapsed timer, for long agent
 * runs. Screen readers hear the label once, not every tick.
 */
export function AgentProgress({
  label = "Churning",
  elapsedSeconds,
  initialSeconds = 0,
  running = true,
  className = "",
  disableAnimation = false,
  accessibilityLabel,
  ...props
}: AgentProgressProps) {
  const reducedMotion = useReducedMotionPreference();
  const reduce = reducedMotion || disableAnimation;
  const controlled = elapsedSeconds !== undefined;
  const [internal, setInternal] = useState(initialSeconds);
  const { color } = useResolveClassNames("text-muted");
  const tint = String(color ?? "gray");
  const active = controlled ? true : running;

  // Restarts only when the timer starts or stops; `internal` seeds the start.
  useEffect(() => {
    if (controlled || !running) return;
    const startedAt = Date.now() - internal * 1000;
    const timer = setInterval(
      () => setInternal((Date.now() - startedAt) / 1000),
      100,
    );
    return () => clearInterval(timer);
  }, [controlled, running]);

  return (
    <View
      accessible
      accessibilityRole="progressbar"
      accessibilityLabel={accessibilityLabel ?? `${label}, in progress`}
      style={styles.row}
      {...props}
    >
      <View
        style={styles.glyph}
        importantForAccessibility="no-hide-descendants"
      >
        {Array.from({ length: 9 }, (_, index) => (
          <Cell
            key={index}
            index={index}
            color={tint}
            reduce={reduce}
            running={active}
          />
        ))}
      </View>
      <Text className={`text-sm font-medium text-muted ${className}`}>
        {label}
      </Text>
      <Text
        className={`font-mono text-sm text-muted/70 ${className}`}
        style={styles.tabular}
      >
        {format(controlled ? elapsedSeconds : internal)}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: "row", alignItems: "center", gap: 12 },
  glyph: {
    width: GLYPH,
    height: GLYPH,
    flexDirection: "row",
    flexWrap: "wrap",
    gap: GAP,
  },
  cell: { width: CELL, height: CELL, borderRadius: 1 },
  tabular: { fontVariant: ["tabular-nums"] },
});

export type { AgentProgressProps } from "./agent-progress";
export { AgentProgress } from "./agent-progress";
export type {
  ReasoningTextProps,
  ReasoningTextVariant,
} from "./reasoning-text";
export { ReasoningText } from "./reasoning-text";
export type { ThinkingShimmerProps } from "./thinking-shimmer";
export { ThinkingShimmer } from "./thinking-shimmer";

import { type ReactNode, useEffect, useState } from "react";
import { Platform, StyleSheet, Text, View, type ViewProps } from "react-native";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";
import { usePresence } from "../../hooks/use-presence";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";
import { CascadeText } from "../../primitives/cascade-text";
import { EASE_OUT } from "../../styles/motion";
import { TextScramble } from "../text-animation/text-scramble";

export type ReasoningTextVariant = "cascade" | "swap" | "scramble";

const DEFAULT_PHRASES = [
  "Thinking",
  "Reading the context",
  "Connecting the details",
  "Forming a response",
];
const SWAP = { duration: 200, easing: EASE_OUT };
const SWAP_REDUCED = { duration: 120 };
const SWAP_DISTANCE = 3;

/** Progress runs 0 (below) → 1 (resting) → 2 (gone above). */
function SwapLayer({
  text,
  appear,
  exiting,
  reduce,
  className,
}: {
  text: string;
  appear: boolean;
  exiting: boolean;
  reduce: boolean;
  className: string;
}) {
  const progress = useSharedValue(appear ? 0 : 1);

  useEffect(() => {
    progress.value = withTiming(exiting ? 2 : 1, reduce ? SWAP_REDUCED : SWAP);
  }, [exiting, progress, reduce]);

  const style = useAnimatedStyle(() => {
    const p = progress.value;
    return {
      opacity: p <= 1 ? p : 2 - p,
      transform: [{ translateY: reduce ? 0 : (1 - p) * SWAP_DISTANCE }],
    };
  }, [reduce]);

  return (
    <Animated.View style={[styles.layer, style]}>
      <Text numberOfLines={1} className={className}>
        {text}
      </Text>
    </Animated.View>
  );
}

function Swap({
  text,
  index,
  reduce,
  className,
}: {
  text: string;
  index: number;
  reduce: boolean;
  className: string;
}) {
  const items = usePresence(`${index}`, text, () =>
    reduce ? SWAP_REDUCED.duration + 40 : SWAP.duration + 40,
  );
  return items.map((item) => (
    <SwapLayer
      key={item.key}
      text={item.value}
      appear={item.appear}
      exiting={item.exiting}
      reduce={reduce}
      className={className}
    />
  ));
}

const SPINNER = ["|", "/", "-", "\\"];
const SPINNER_STEP = 200;

/** A terminal line spinner set in the phrase's own type, so they share a baseline. */
function Spinner({
  className,
  reduce,
}: {
  className: string;
  reduce: boolean;
}) {
  const [frame, setFrame] = useState(0);
  useEffect(() => {
    // Reduced motion slows the swap rather than stopping it; nothing moves.
    const timer = setInterval(
      () => setFrame((current) => (current + 1) % SPINNER.length),
      reduce ? SPINNER_STEP * 2.5 : SPINNER_STEP,
    );
    return () => clearInterval(timer);
  }, [reduce]);
  return (
    <Text className={className} style={styles.spinner}>
      {SPINNER[frame]}
    </Text>
  );
}

export type ReasoningTextProps = Omit<ViewProps, "children"> & {
  /** Status phrases, cycled in order. An ellipsis is added to each. */
  phrases?: string[];
  /** How one phrase gives way to the next. Defaults to "cascade". */
  variant?: ReasoningTextVariant;
  /** Milliseconds each phrase shows. Defaults to 1800, at least 600. */
  interval?: number;
  /** Replaces the spinning ASCII indicator. Pass `null` to hide it. */
  indicator?: ReactNode;
  /** Text size utilities, such as `text-base`. */
  className?: string;
  /** Swaps phrases without motion, independently of the system preference. */
  disableAnimation?: boolean;
};

/**
 * A status line that cycles through what an agent is doing: letters roll in,
 * phrases swap, or glyphs scramble into place. The longest phrase reserves
 * the width, so nothing around it shifts.
 */
export function ReasoningText({
  phrases = DEFAULT_PHRASES,
  variant = "cascade",
  interval = 1800,
  indicator,
  className = "",
  disableAnimation = false,
  accessibilityLabel,
  ...props
}: ReasoningTextProps) {
  const reducedMotion = useReducedMotionPreference();
  const reduce = reducedMotion || disableAnimation;
  const [index, setIndex] = useState(0);
  const count = phrases.length;
  const step = Math.max(600, interval);

  useEffect(() => {
    if (count < 2) return;
    const timer = setInterval(() => setIndex((i) => (i + 1) % count), step);
    return () => clearInterval(timer);
  }, [count, step]);

  const phrase = phrases[index % Math.max(count, 1)] ?? "";
  const text = `${phrase}…`;
  const textClass = `text-sm font-medium text-muted ${className}`;

  return (
    <View
      accessible
      accessibilityLiveRegion="polite"
      accessibilityLabel={accessibilityLabel ?? phrase}
      style={styles.row}
      {...props}
    >
      {indicator === undefined ? (
        <Spinner className={textClass} reduce={reduce} />
      ) : (
        indicator
      )}
      <View style={[styles.slot, variant !== "swap" && styles.overflow]}>
        {/* Lays out every phrase, invisibly, so the slot is as wide as the widest. */}
        <View style={styles.reserve}>
          {phrases.map((candidate, position) => (
            <Text
              key={`${position}-${candidate}`}
              numberOfLines={1}
              className={textClass}
              style={position > 0 && styles.collapsed}
            >
              {`${candidate}…`}
            </Text>
          ))}
        </View>
        {variant === "cascade" ? (
          <View style={styles.layer}>
            <CascadeText
              textKey={`${index}`}
              text={text}
              className={textClass}
              reduce={reduce}
            />
          </View>
        ) : variant === "swap" ? (
          <Swap
            text={text}
            index={index}
            reduce={reduce}
            className={textClass}
          />
        ) : (
          <View style={styles.layer}>
            <TextScramble
              text={text}
              disableAnimation={reduce}
              className={textClass}
              style={styles.tabular}
            />
          </View>
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: "row", alignItems: "center", gap: 8 },
  slot: { overflow: "hidden" },
  reserve: { opacity: 0 },
  collapsed: { height: 0 },
  // Letter-by-letter layout and scrambling glyphs can run a little wider than
  // the kerned phrase that reserves the width; let them.
  overflow: { overflow: "visible" },
  layer: {
    position: "absolute",
    left: 0,
    right: 0,
    top: 0,
    bottom: 0,
    justifyContent: "center",
  },
  tabular: { fontVariant: ["tabular-nums"] },
  spinner: {
    width: 12,
    textAlign: "center",
    fontFamily: Platform.select({ ios: "Menlo", default: "monospace" }),
  },
});

import {
  TextShimmer,
  type TextShimmerProps,
} from "../text-animation/text-shimmer";

export type ThinkingShimmerProps = Omit<TextShimmerProps, "children"> & {
  /** Defaults to "Thinking…". */
  children?: string;
};

/** A highlight sweeping across a muted status line while an agent thinks. */
export function ThinkingShimmer({
  children = "Thinking…",
  duration = 1800,
  className = "",
  ...props
}: ThinkingShimmerProps) {
  return (
    <TextShimmer
      duration={duration}
      className={`text-sm font-medium ${className}`}
      {...props}
    >
      {children}
    </TextShimmer>
  );
}

