  },
  active: {
    width: 12,
    height: 12,
    alignItems: "center",
    justifyContent: "center",
  },
  halo: { borderRadius: 6 },
  dot: { width: 6, height: 6, borderRadius: 3 },
  // From under the mark, through the row's bottom padding and the gap, to the
  // top of the next mark.
  connector: {
    position: "absolute",
    left: 6 + 7.5,
    top: 4 + 2 + 16 + 2,
    bottom: -4,
    width: 1,
  },
  pending: { width: 11, height: 11, borderRadius: 6, borderWidth: 1.5 },
  queryRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 10,
    minHeight: 28,
  },
  resultRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
    minHeight: 28,
  },
  resultIcon: {
    width: 20,
    height: 20,
    alignItems: "center",
    justifyContent: "center",
  },
  resultText: {
    flex: 1,
    minWidth: 0,
