import {
  normalizeTokens,
  Prism,
  type PrismTheme,
  themes,
} from "prism-react-renderer";
import { useMemo } from "react";
import { useUniwind } from "uniwind";

export type CodeLanguage =
  | "bash"
  | "css"
  | "go"
  | "javascript"
  | "json"
  | "jsx"
  | "kotlin"
  | "markdown"
  | "python"
  | "rust"
  | "sql"
  | "swift"
  | "text"
  | "tsx"
  | "typescript"
  | "yaml";

export type CodeToken = { content: string; color?: string };
export type CodeTokenLines = CodeToken[][];

// Prism's bundle has no shell grammar; this covers what agents usually run.
if (!Prism.languages.bash) {
  Prism.languages.bash = {
    comment: { pattern: /(^|\s)#.*/, lookbehind: true },
    string: { pattern: /(["'])(?:\\.|(?!\1)[^\\])*\1/, greedy: true },
    variable: /\$(?:\w+|\{[^}]+\})/,
    function: { pattern: /(^|[|;&]\s*|\$\s+)[\w./-]+/m, lookbehind: true },
    keyword:
      /\b(?:if|then|else|elif|fi|for|while|do|done|case|esac|in|function|export|return)\b/,
    property: /(^|\s)--?[\w-]+/,
    operator: /&&|\|\||[|;&<>]/,
    number: /\b\d+(?:\.\d+)?\b/,
  };
}

const LIGHT = themes.github;
const DARK = themes.oneDark;

function palette(theme: PrismTheme) {
  const colors = new Map<string, string>();
  for (const style of theme.styles) {
    const color = style.style.color;
    if (!color) continue;
    for (const type of style.types) colors.set(type, color);
  }
  return colors;
}
const PALETTES = { light: palette(LIGHT), dark: palette(DARK) };

// Small, bounded cache: streaming code re-tokenizes a growing string.
const cache = new Map<string, string[][][]>();
const CACHE_SIZE = 64;

/** Splits code into lines of tokens, each token tagged with its Prism types. */
function tokenize(code: string, language: CodeLanguage) {
  const key = `${language}\u0000${code}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const grammar = language === "text" ? undefined : Prism.languages[language];
  const lines = grammar
    ? normalizeTokens(Prism.tokenize(code, grammar)).map((line) =>
        line.map((token) => [token.content, ...token.types]),
      )
    : code.split("\n").map((line) => [[line, "plain"]]);
  cache.set(key, lines);
  if (cache.size > CACHE_SIZE)
    cache.delete(cache.keys().next().value as string);
  return lines;
}

/**
 * Syntax-highlighted lines for the current light or dark theme. Tokenizing is
 * synchronous, so streamed code never flashes back to plain text.
 */
export function useCodeTokens(
  code: string,
  language: CodeLanguage,
): CodeTokenLines {
  const { theme } = useUniwind();
  const colors = theme === "dark" ? PALETTES.dark : PALETTES.light;
  return useMemo(
    () =>
      tokenize(code, language).map((line) =>
        line.map(([content = "", ...types]) => {
          let color: string | undefined;
          for (const type of types) color = colors.get(type) ?? color;
          return { content, color };
        }),
      ),
    [code, colors, language],
  );
}

import { type ReactNode, useEffect, useRef } from "react";
import { StyleSheet, View, type ViewStyle } from "react-native";
import Animated, {
  measure,
  useAnimatedRef,
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";
import { scheduleOnUI } from "react-native-worklets";
import { EASE_OUT } from "../styles/motion";

const OPEN = { duration: 220, easing: EASE_OUT };
const CLOSE = { duration: 140, easing: EASE_OUT };
const DROP = 4;
// The height while settled open: unconstrained, so growing content just flows.
const NATURAL = -1;

export type DisclosureProps = {
  open: boolean;
  /** Snaps open and closed, keeping only the fade. */
  reduce: boolean;
  /** Caps the open height; content clips beyond it. */
  maxHeight?: number;
  style?: ViewStyle;
  children: ReactNode;
};

/**
 * Collapsible content shared by the agent components: the height eases
 * between closed and the content's size while the content fades and drops 4
 * points into place. Settled open, the height is left alone, so content that
 * grows (streamed rows, new sources) is never clipped. Closed content is
 * hidden from screen readers and touches.
 */
export function Disclosure({
  open,
  reduce,
  maxHeight,
  style,
  children,
}: DisclosureProps) {
  // The content's height, kept current by layout events; measuring on demand
  // can read 0 for content inside a scroll view.
  const contentHeight = useSharedValue(0);
  const clipRef = useAnimatedRef<Animated.View>();
  const height = useSharedValue(open ? NATURAL : 0);
  const shown = useSharedValue(open ? 1 : 0);
  const mounted = useRef(false);

  useEffect(() => {
    // The first render is already in place.
    if (!mounted.current) {
      mounted.current = true;
      return;
    }
    const cap = maxHeight ?? Number.POSITIVE_INFINITY;
    scheduleOnUI(() => {
      "worklet";
      // Real sizes, read on the UI thread at the moment of the change.
      const full = Math.min(contentHeight.value, cap);
      if (open) {
        const from = height.value === NATURAL ? full : height.value;
        if (reduce) {
          height.value = NATURAL;
        } else {
          height.value = from;
          height.value = withTiming(full, OPEN, (done) => {
            if (done) height.value = NATURAL;
          });
        }
      } else {
        const clip = measure(clipRef);
        const from =
          height.value === NATURAL ? (clip?.height ?? full) : height.value;
        height.value = from;
        height.value = reduce ? 0 : withTiming(0, CLOSE);
      }
    });
    shown.value = withTiming(
      open ? 1 : 0,
      reduce ? { duration: 0 } : open ? OPEN : CLOSE,
    );
  }, [clipRef, contentHeight, height, maxHeight, open, reduce, shown]);

  const clipStyle = useAnimatedStyle(() =>
    // Settled open, the clip follows the content's measured height.
    height.value === NATURAL
      ? {
          height: Math.min(
            contentHeight.value,
            maxHeight ?? Number.POSITIVE_INFINITY,
          ),
        }
      : { height: height.value },
  );
  const contentStyle = useAnimatedStyle(
    () => ({
      opacity: shown.value,
      transform: [{ translateY: reduce ? 0 : (1 - shown.value) * -DROP }],
    }),
    [reduce],
  );

  return (
    <Animated.View
      ref={clipRef}
      pointerEvents={open ? "auto" : "none"}
      accessibilityElementsHidden={!open}
      importantForAccessibility={open ? "auto" : "no-hide-descendants"}
      style={[styles.clip, clipStyle, style]}
    >
      {/* Absolutely placed, so the content keeps its natural height while the
          clip around it is short, and can be measured at any time. */}
      <Animated.View style={[styles.content, contentStyle]}>
        <View
          style={styles.measure}
          onLayout={({ nativeEvent }) => {
            contentHeight.value = nativeEvent.layout.height;
          }}
        >
          {children}
        </View>
      </Animated.View>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  clip: { overflow: "hidden" },
  content: { position: "absolute", left: 0, right: 0, top: 0 },
  measure: { flexShrink: 0 },
});

import { useEffect } from "react";
import type { ColorValue } from "react-native";
import Animated, {
  cancelAnimation,
  Easing,
  ReduceMotion,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withTiming,
} from "react-native-reanimated";
import { RingGlyph } from "./agent-icons";

/**
 * A spinning ring for busy states. Reduced motion holds it still; the ring
 * still reads as "in progress".
 */
export function SpinGlyph({
  size = 16,
  color,
  reduce,
}: {
  size?: number;
  color?: ColorValue;
  reduce: boolean;
}) {
  const turn = useSharedValue(0);

  useEffect(() => {
    if (reduce) {
      cancelAnimation(turn);
      turn.value = 0;
      return;
    }
    turn.value = 0;
    turn.value = withRepeat(
      withTiming(1, {
        duration: 900,
        easing: Easing.linear,
        reduceMotion: ReduceMotion.Never,
      }),
      -1,
      false,
    );
    return () => cancelAnimation(turn);
  }, [reduce, turn]);

  const style = useAnimatedStyle(() => ({
    transform: [{ rotate: `${turn.value * 360}deg` }],
  }));

  return (
    <Animated.View style={style}>
      <RingGlyph size={size} color={color} />
    </Animated.View>
  );
}

import { Easing, ReduceMotion } from "react-native-reanimated";

// Mirrors beUI's lib/ease.ts so native motion matches the web library.

export const EASE_OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const EASE_IN_OUT = Easing.bezier(0.77, 0, 0.175, 1);

/** Press feedback on buttons and other tappable surfaces. */
export const SPRING_PRESS = {
  stiffness: 500,
  damping: 30,
  mass: 0.6,
  reduceMotion: ReduceMotion.System,
} as const;

/** Content swaps: label and icon slots trading places inside a control. */
export const SPRING_SWAP = {
  stiffness: 460,
  damping: 30,
  mass: 0.55,
  reduceMotion: ReduceMotion.System,
} as const;

/** Shared-layout glides: pills, indicators and panels moving between positions. */
export const SPRING_LAYOUT = {
  stiffness: 360,
  damping: 32,
  mass: 0.6,
  reduceMotion: ReduceMotion.System,
} as const;

/** Dragged handles and fills; critically damped so values never rebound off an end. */
export const SPRING_GLIDE = {
  stiffness: 700,
  damping: 50,
  mass: 0.5,
  reduceMotion: ReduceMotion.System,
} as const;

export const motion = {
  press: SPRING_PRESS,
  swap: SPRING_SWAP,
  layout: SPRING_LAYOUT,
  glide: SPRING_GLIDE,
  exit: { duration: 160, easing: EASE_OUT, reduceMotion: ReduceMotion.System },
  fade: { duration: 150, reduceMotion: ReduceMotion.System },
} as const;

